FROM (SELECT ProductId, Region, Amount FROM dbo.Sales WHERE SaleDate >= @from AND SaleDate < @to) s
PIVOT (SUM(Amount) FOR Region IN (' + @cols + N')) p;';
EXEC sys.sp_executesql @sql, N'@from date, @to date', @from = @from, @to = @to;

